#!/usr/bin/env python3
"""Old-source red, current green, actual classifier mutation red/restored green."""
import argparse,hashlib,json,subprocess,sys
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--scratch',type=Path,required=True);p.add_argument('--evidence',type=Path,required=True);a=p.parse_args();a.scratch.mkdir(parents=True,exist_ok=False);a.evidence.mkdir(parents=True,exist_ok=False);root=Path(__file__).resolve().parent;rows=[]
def run(name,args,expected):
 argv=[sys.executable,'-B',str(root/'classification_fixture.py'),*args];r=subprocess.run(argv,capture_output=True);(a.evidence/(name+'.stdout.json')).write_bytes(r.stdout);(a.evidence/(name+'.stderr.log')).write_bytes(r.stderr);ok=r.returncode==expected and (bool(json.loads(r.stdout)['failures']) if expected else not json.loads(r.stdout)['failures']);rows.append({'name':name,'argv':argv,'exit_code':r.returncode,'expected_exit_code':expected,'passed':ok,'stdout_sha256':hashlib.sha256(r.stdout).hexdigest()});assert ok,(name,r.stdout,r.stderr)
run('original-production-source-red',['--legacy'],1);run('current-production-source-green',[],0)
original=(root/'notice_types.py').read_bytes();mutant=a.scratch/'notice_types_mutant.py';source=original.decode();source=source.replace("    return {'classification_version':", "    kind='full-license-text-candidate';full=True\n    return {'classification_version':");assert source.encode()!=original;mutant.write_text(source);run('mutated-production-classifier-red',['--module',str(mutant.resolve())],1);mutant.write_bytes(original);run('restored-production-classifier-green',['--module',str(mutant.resolve())],0)
false_source=original.decode().replace("    return {'classification_version':", "    kind='license-reference-or-provenance-notice';full=False\n    return {'classification_version':");mutant.write_text(false_source);run('mutated-production-classifier-false-negative-red',['--module',str(mutant.resolve())],1);mutant.write_bytes(original);run('restored-production-classifier-positive-green',['--module',str(mutant.resolve())],0);mutant.unlink()
result={'status':'VERIFIED','runs':len(rows),'original_candidate_manifest_sha256':hashlib.sha256((root/'baseline-v2/sample-production-pack/manifest.json').read_bytes()).hexdigest(),'production_classifier_sha256':hashlib.sha256(original).hexdigest(),'controls':rows,'mutant_removed':True};(a.evidence/'controls.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({k:v for k,v in result.items() if k!='controls'}))
